INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'platform_owner', 'Dueño de la plataforma', 'Equipo EscudoSST: planes, cuentas, cobros, soporte. No ve datos de empresas salvo acceso de soporte autorizado y registrado.', 'platform_owner', 'platform', true, false, true, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'platform_support', 'Soporte de la plataforma', 'Atiende tickets; acceso temporal a una empresa solo con autorización del administrador de cuenta.', 'platform_support', 'platform', true, false, true, true) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'account_admin', 'Administrador de cuenta', 'Dueño de la suscripción del cliente: usuarios, plan, facturación, empresas.', 'account_admin', 'account', true, false, true, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'consultant', 'Consultor SST', 'Usuario de una consultora que gestiona varias empresas cliente desde el panel multi-cliente.', 'consultant', 'company', true, false, true, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'sst_manager', 'Jefe SST / Responsable del SG-SST', 'Gestiona todo el sistema de gestión SST de la empresa.', 'sst_manager', 'company', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'sst_supervisor', 'Supervisor SST', 'Figura legal en empresas con menos de 20 trabajadores, o supervisor de campo.', 'sst_supervisor', 'company', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'committee_member', 'Miembro del Comité SST', 'Aprueba programas, revisa actas, acuerdos, inspecciones y accidentes.', 'committee_member', 'company', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'management', 'Gerencia', 'Lectura de indicadores, revisión por la dirección, aprobación de política y presupuesto.', 'management', 'company', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'area_lead', 'Jefe de área / línea', 'Ejecuta inspecciones, ATS, charlas, PETAR y cierra acciones de su área.', 'area_lead', 'scoped', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'occupational_doctor', 'Médico ocupacional', 'Único con acceso a datos médicos (EMOs, vigilancia, notas clínicas), con clave adicional.', 'occupational_doctor', 'company', true, true, true, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'health_staff', 'Personal de salud', 'Enfermería o asistente: agenda EMOs, descansos; acceso médico limitado.', 'health_staff', 'company', true, true, true, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'hr', 'Recursos Humanos', 'Carga y mantiene trabajadores, puestos y ausentismo; ve aptitud, no diagnósticos.', 'hr', 'company', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'trainer', 'Capacitador', 'Dicta y gestiona los cursos que se le asignan: contenidos, evaluaciones y calificaciones; matricula solo si el administrador lo permite; registra su disponibilidad.', 'trainer', 'scoped', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'external_learner', 'Participante externo', 'Persona que no es trabajador de la empresa y compra o recibe un curso (venta de cursos): cursa, rinde evaluaciones y descarga su certificado.', 'external_learner', 'own', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'worker', 'Trabajador', 'App/PWA: firma, capacitaciones, fotocheck, reportes, EPP, sus resultados médicos propios.', 'worker', 'own', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'contractor_admin', 'Administrador de contratista', 'Portal: sube documentos de su empresa y trabajadores, SCTR, solicita acreditación.', 'contractor_admin', 'own', true, false, false, false) ON CONFLICT DO NOTHING;
INSERT INTO roles (account_id, code, name, description, base_role_code, scope_level, is_system, is_medical, requires_mfa, is_temporary) VALUES (NULL, 'external_auditor', 'Auditor externo', 'Lectura temporal acotada a un periodo y módulos, con vencimiento.', 'external_auditor', 'scoped', true, false, false, true) ON CONFLICT DO NOTHING;
